import { computed } from 'vue';
/** 公共输入允许清空或多种标量，页面模型只接收自己声明的合法值。 */
export function choiceModel(read, write, choices) {
	return computed({
		get: read,
		set(value) {
			if (choices.some((choice) => Object.is(choice, value))) write(value);
		}
	});
}
export function booleanModel(read, write) {
	return computed({
		get: read,
		set(value) {
			if (typeof value === 'boolean') write(value);
		}
	});
}
export function textModel(read, write) {
	return computed({
		get: read,
		set(value) {
			if (typeof value === 'string') write(value);
		}
	});
}

import { computed, reactive, shallowRef, watch } from 'vue';
/** 合成前端宿主：状态按身份隔离，导航打开实际本地内容，不连接业务服务。 */
export function createWorkplaceFixture(locale) {
	const controls = reactive({
		mode: 'normal',
		delayMs: 80,
		identity: 1,
		readonly: false,
		disabled: false,
		denied: false,
		navigation: 'normal'
	});
	const audit = reactive({ reads: 0, aborted: 0, actions: 0, navigations: 0 });
	const destination = shallowRef();
	const completed = new Map();
	let disposed = false;
	const pending = new Set();
	const choose = (zh, en) => (locale() === 'en' ? en : zh);
	const context = computed(() => ({
		scope: 'workplace-demo',
		identity: String(controls.identity),
		revision: `${locale()}:${controls.mode}:${controls.delayMs}`
	}));
	let navigationEpoch = 0;
	const stopNavigation = watch(
		() => [context.value, controls.disabled, controls.denied, controls.navigation],
		() => {
			navigationEpoch++;
		},
		{ flush: 'sync' }
	);
	const current = (captured) =>
		!disposed && JSON.stringify(captured) === JSON.stringify(context.value);
	function wait(signal, milliseconds) {
		return new Promise((resolve, reject) => {
			let settled = false;
			const finish = (abort) => {
				if (settled) return;
				settled = true;
				clearTimeout(timer);
				signal.removeEventListener('abort', cancel);
				pending.delete(cancel);
				if (abort) {
					audit.aborted++;
					reject(new DOMException('Aborted', 'AbortError'));
				} else resolve();
			};
			const cancel = () => finish(true);
			const timer = setTimeout(() => finish(false), milliseconds);
			pending.add(cancel);
			if (signal.aborted || disposed) cancel();
			else signal.addEventListener('abort', cancel, { once: true });
		});
	}
	function data() {
		const empty = controls.mode === 'empty';
		const name =
			controls.identity === 1 ? choose('林岚', 'Lin Lan') : choose('周远', 'Zhou Yuan');
		const projects = [
			[
				choose('设计系统升级', 'Design system upgrade'),
				choose(
					'统一团队日常界面与交互规范，让每一次协作更清晰。',
					'Unify everyday interfaces and interactions for clearer collaboration.'
				),
				name,
				68,
				'active'
			],
			[
				choose('设备台账体验优化', 'Asset register experience'),
				choose(
					'梳理设备全生命周期信息，改善查询、维护与交接体验。',
					'Improve asset information, maintenance and handovers.'
				),
				choose('周远', 'Zhou Yuan'),
				20,
				'planned'
			],
			[
				choose('服务运行手册', 'Service operations handbook'),
				choose(
					'整理处理流程和场景边界，形成团队可持续维护的工作手册。',
					'Document workflows and boundaries in a maintainable team handbook.'
				),
				choose('陈晓', 'Chen Xiao'),
				100,
				'done'
			]
		];
		const tasks = [
			choose('审核设备采购申请', 'Review asset purchase request'),
			choose('确认设计系统更新', 'Confirm design system updates'),
			choose('整理本周项目进展', 'Prepare weekly project update')
		];
		return {
			snapshot: {
				version: 'local-workplace-1',
				workspace: {
					title: choose('下午好，', 'Good afternoon, ') + name,
					description: choose(
						'先从最重要的一项开始。',
						'Start with the most important task.'
					),
					name
				},
				metrics: [],
				tasks: empty
					? []
					: tasks.map((title, i) => ({
							id: i,
							title,
							description: choose('本地演示待办', 'Local demo task'),
							status: { label: choose('待处理', 'Pending') },
							assignees: [],
							target: 'tasks',
							permission: 'view',
							dueAt: i < 2 ? '2026-11-03T18:00:00+08:00' : '2026-11-04T18:00:00+08:00'
						})),
				shortcuts: empty
					? []
					: [
							choose('任务管理', 'Task management'),
							choose('项目资料', 'Project resources'),
							choose('团队知识', 'Team knowledge'),
							choose('个人设置', 'Personal settings')
						].map((label, i) => ({
							id: i,
							label,
							description: label,
							target: ['tasks', 'projects', 'knowledge', 'settings'][i],
							permission: 'view'
						})),
				activities: empty
					? []
					: [
							choose(
								'林岚更新了「设备台账体验优化」的项目进展。',
								'Lin Lan updated the asset register project.'
							),
							choose(
								'周远完成了「服务运行手册」的内容评审。',
								'Zhou Yuan reviewed the service operations handbook.'
							),
							choose(
								'陈晓创建了新任务「补充采购申请信息」。',
								'Chen Xiao created a purchase information task.'
							)
						].map((text, i) => ({
							id: i,
							text,
							at: [
								'2026-11-03T14:00:00+08:00',
								'2026-11-03T13:30:00+08:00',
								'2026-11-03T10:20:00+08:00'
							][i],
							target: 'tasks',
							permission: 'view'
						}))
			},
			projects: empty
				? []
				: projects.map(([name, description, owner, progress, status], i) => ({
						id: String(i),
						name,
						description,
						owner,
						progress,
						status,
						target: 'project-' + i,
						permission: 'view'
					})),
			teams: empty
				? []
				: [
						choose('产品体验组', 'Product experience'),
						choose('研发运营组', 'Engineering operations'),
						choose('平台工程组', 'Platform engineering')
					].map((name, i) => ({
						id: String(i),
						name,
						description: choose(
							'协作、项目资料与团队职责',
							'Collaboration, resources and team responsibilities'
						),
						target: 'team-' + i,
						permission: 'view'
					})),
			week: empty
				? []
				: [12, 18, 15, 24, 21, 8, 6].map((value, i) => ({
						id: String(i),
						label:
							locale() === 'en'
								? ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'][i]
								: ['周一', '周二', '周三', '周四', '周五', '周六', '周日'][i],
						value
					})),
			completedTaskIds: empty ? [] : [...(completed.get(controls.identity) ?? [])]
		};
	}
	const service = {
		async load(input) {
			audit.reads++;
			const mode = controls.mode;
			await wait(input.signal, controls.delayMs);
			if (
				!current({ scope: input.scope, identity: input.identity, revision: input.revision })
			)
				throw new DOMException('Aborted', 'AbortError');
			if (mode === 'error') throw Error(choose('合成读取失败', 'Synthetic read failed'));
			return data();
		}
	};
	const actions = [
		{
			id: 'toggle',
			label: 'toggle',
			permission: 'edit',
			async run(input) {
				const captured = {
					scope: input.scope,
					identity: input.identity,
					revision: input.revision
				};
				await wait(input.signal, controls.delayMs);
				if (
					!current(captured) ||
					input.signal.aborted ||
					controls.disabled ||
					controls.readonly ||
					controls.denied
				)
					throw new DOMException('Aborted', 'AbortError');
				const set = completed.get(controls.identity) ?? new Set();
				if (set.has(input.task.id)) set.delete(input.task.id);
				else set.add(input.task.id);
				completed.set(controls.identity, set);
				audit.actions++;
			}
		}
	];
	const navigator = {
		async navigate(location) {
			const epoch = navigationEpoch;
			const captured = { ...context.value },
				mode = controls.navigation;
			// 旧navigator无signal参数：宿主自行保护异步导航的身份和策略副作用。
			const controller = new AbortController();
			await wait(controller.signal, controls.delayMs);
			if (
				!current(captured) ||
				epoch !== navigationEpoch ||
				controls.disabled ||
				controls.denied ||
				mode !== controls.navigation ||
				mode === 'cancel'
			)
				return false;
			if (mode === 'error')
				throw Error(choose('合成导航失败', 'Synthetic navigation failed'));
			if (typeof location !== 'string') return false;
			const key = location.replace('/dashboard/workplace/', ''),
				model = data();
			const project = model.projects.find((row) => row.target === key),
				team = model.teams.find((row) => row.target === key),
				shortcut = model.snapshot.shortcuts.find((row) => row.target === key);
			if (project)
				destination.value = {
					title: project.name,
					description: project.description,
					details: [project.owner, `${project.progress}%`]
				};
			else if (team)
				destination.value = {
					title: team.name,
					description: team.description,
					details: model.projects.map((row) => row.name)
				};
			else if (shortcut)
				destination.value = {
					title: shortcut.label,
					description: choose(
						'当前身份的本地演示工作区',
						'Local demo workspace for this identity'
					),
					details:
						key === 'tasks'
							? model.snapshot.tasks.map((row) => row.title)
							: key === 'projects'
								? model.projects.map((row) => row.name)
								: key === 'knowledge'
									? [
											choose('服务运行手册', 'Service operations handbook'),
											choose(
												'设计系统协作规范',
												'Design system collaboration guide'
											)
										]
									: [
											model.snapshot.workspace.name,
											choose(
												'语言与外观由演示选项配置',
												'Configure language and appearance in demo options'
											)
										]
				};
			else return false;
			audit.navigations++;
			return true;
		}
	};
	const host = computed(() => ({
		context: context.value,
		service,
		actions,
		navigator,
		readonly: controls.readonly,
		disabled: controls.disabled,
		allowed: () => !controls.denied,
		targets:
			controls.navigation === 'missing'
				? []
				: [
						'tasks',
						'projects',
						'knowledge',
						'settings',
						'project-0',
						'project-1',
						'project-2',
						'team-0',
						'team-1',
						'team-2'
					].map((id) => ({
						id,
						location: '/dashboard/workplace/' + id,
						permission: 'view'
					}))
	}));
	return {
		controls,
		audit,
		host,
		destination,
		switchIdentity() {
			controls.identity = controls.identity === 1 ? 2 : 1;
			destination.value = undefined;
		},
		back() {
			destination.value = undefined;
		},
		dispose() {
			if (disposed) return;
			disposed = true;
			stopNavigation();
			for (const cancel of [...pending]) cancel();
			destination.value = undefined;
		}
	};
}

import { computed, shallowRef, watch } from 'vue';
import { createWorkbench, validateSnapshot } from '../../workbench/Workbench.js';
const contextKey = (context) => JSON.stringify([context.scope, context.identity, context.revision]);
const idKey = (id) => JSON.stringify([typeof id, id]);
/** 完整局部模型必须与旧快照一起通过，拒绝跨身份拼接。 */
export function validateWorkplace(input) {
	const snapshot = validateSnapshot(input.snapshot);
	for (const rows of [input.projects, input.teams, input.week]) {
		if (
			!Array.isArray(rows) ||
			new Set(rows.map((row) => row?.id)).size !== rows.length ||
			rows.some((row) => !row || typeof row.id !== 'string' || !row.id.trim())
		)
			throw Error('Invalid workplace rows');
	}
	for (const row of [...input.projects, ...input.teams]) {
		if (
			typeof row.name !== 'string' ||
			typeof row.description !== 'string' ||
			typeof row.target !== 'string' ||
			!row.target.trim() ||
			(row.permission !== undefined && typeof row.permission !== 'string')
		)
			throw Error('Invalid workplace target');
	}
	if (
		input.projects.some(
			(row) =>
				!Number.isFinite(row.progress) ||
				row.progress < 0 ||
				row.progress > 100 ||
				typeof row.owner !== 'string' ||
				!['active', 'planned', 'done'].includes(row.status)
		)
	)
		throw Error('Invalid project progress');
	if (
		input.week.some(
			(row) =>
				typeof row.label !== 'string' ||
				!Number.isFinite(row.value) ||
				row.value === null ||
				row.value < 0
		)
	)
		throw Error('Invalid weekly data');
	const taskIds = new Set(snapshot.tasks.map((row) => idKey(row.id)));
	if (
		!Array.isArray(input.completedTaskIds) ||
		new Set(input.completedTaskIds.map(idKey)).size !== input.completedTaskIds.length ||
		input.completedTaskIds.some((id) => !taskIds.has(idKey(id)))
	)
		throw Error('Invalid completed tasks');
	const copy = structuredClone({ ...input, snapshot });
	function freeze(value) {
		Object.freeze(value);
		for (const child of Object.values(value))
			if (child && typeof child === 'object') freeze(child);
	}
	freeze(copy);
	return copy;
}
/** 原controller继续独占权限、取消、动作及导航；适配器只原子配对局部模型。 */
export function createWorkplace(getHost) {
	const accepted = shallowRef();
	let staged;
	let disposed = false;
	const adapters = new WeakMap();
	function adapter(service) {
		let result = adapters.get(service);
		if (!result) {
			result = {
				async load(input) {
					const model = validateWorkplace(await service.load(input));
					if (
						!disposed &&
						!input.signal.aborted &&
						getHost().service === service &&
						contextKey(getHost().context) === contextKey(input)
					)
						staged = { key: contextKey(input), service, model };
					return model.snapshot;
				}
			};
			adapters.set(service, result);
		}
		return result;
	}
	const stop = watch(
		[() => contextKey(getHost().context), () => getHost().service],
		() => {
			accepted.value = undefined;
			staged = undefined;
		},
		{ flush: 'sync' }
	);
	const adapted = computed(() => {
		const host = getHost();
		return {
			...host,
			service: adapter(host.service),
			onEvent(event) {
				if (event.type === 'load') {
					accepted.value = undefined;
					staged = undefined;
				}
				if (
					event.type === 'loaded' &&
					staged &&
					staged.key === contextKey(getHost().context) &&
					staged.service === getHost().service
				)
					accepted.value = staged;
				host.onEvent?.(event);
			}
		};
	});
	const controller = createWorkbench(() => adapted.value);
	const model = computed(() => {
		const value = accepted.value;
		return !disposed &&
			!controller.loading.value &&
			!controller.error.value &&
			controller.snapshot.value &&
			value?.key === contextKey(getHost().context) &&
			value.service === getHost().service
			? value.model
			: null;
	});
	async function toggle(task) {
		if (await controller.runAction(task, 'toggle')) await controller.refresh();
	}
	return {
		controller,
		model,
		toggle,
		dispose() {
			if (disposed) return;
			disposed = true;
			stop();
			controller.dispose();
			accepted.value = undefined;
			staged = undefined;
		}
	};
}

import { createApp, shallowRef } from 'vue';
import { provideAsamData } from '@asam-ui/ui';
import { AsamI18nKey, createAsamI18n } from '@asam-ui/ui/i18n';
import App from './App.vue';
/** 演示边界拥有客户端与语言实例；传入的外部语言实例由调用者释放。 */
export function mountWorkplaceWorkspace(element, host, onError) {
	const locale = shallowRef('zh-CN');
	const i18n = host?.i18n ?? createAsamI18n(() => ({ locale: locale.value }));
	const app = createApp(App, {
		externalI18n: host?.i18n,
		inheritAppearance: host?.inheritAppearance,
		diagnostics: host?.diagnostics,
		onLocale: (value) => {
			locale.value = value;
		}
	});
	app.provide(AsamI18nKey, i18n);
	provideAsamData(app, {}, { scope: 'dashboard-workplace-demo' });
	if (onError) app.config.errorHandler = onError;
	app.mount(element);
	let disposed = false;
	return () => {
		if (disposed) return;
		disposed = true;
		app.unmount();
		if (!host?.i18n) i18n.dispose();
	};
}

/** Validate before invoking the engine. Null is a gap, zero and signed decimals are values. */
export function validateSeries(series, scope) {
	const ids = new Set();
	for (const item of series) {
		if (!item.id || ids.has(item.id))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.seriesId')
				: 'series ID 缺失或重复';
		ids.add(item.id);
		if (!['line', 'bar', 'pie'].includes(item.kind))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.chartKind')
				: '未注册的图表类型';
		const points = new Set();
		for (const point of item.points) {
			if (!point.id || points.has(point.id))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.pointId')
					: 'point ID 缺失或重复';
			points.add(point.id);
			if (point.value !== null && !Number.isFinite(point.value))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.finite')
					: '图表值必须为有限数字或 null';
			if (item.kind === 'pie' && point.value !== null && point.value < 0)
				return scope?.enabled.value
					? scope.t('app.templates.visualization.negativePie')
					: '饼图不支持负数；请使用折线或柱图';
		}
	}
}

import { init, use } from 'echarts/core';
import { LineChart, BarChart, PieChart } from 'echarts/charts';
import {
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent
} from 'echarts/components';
import { SVGRenderer } from 'echarts/renderers';
use([
	LineChart,
	BarChart,
	PieChart,
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent,
	SVGRenderer
]);
export { init };

/** Vite resolves this marker to its own emitted entry, including the configured base URL.
 * A fresh URL on retry avoids the browser's cached rejected dynamic-import promise.
 * No remote scripts, copied engine code or alternate dependency instance are used.
 */
let loaded;
export async function loadEngine(attempt) {
	if (loaded) return loaded;
	const url = new URL('__ASAM_ENGINE_URL__', import.meta.url);
	if (attempt > 0) url.searchParams.set('asam-retry', String(attempt));
	const engine = await import(/* @vite-ignore */ url.href);
	loaded = engine;
	return engine;
}

.viz-shell {
	--viz-bg: var(--asam-color-surface-muted, #f3f6f7);
	--viz-surface: var(--asam-color-surface, #fff);
	--viz-text: var(--asam-color-text-primary, #20363e);
	--viz-border: var(--asam-color-border, #d8e1e5);
	--viz-control: 32px;
	background: var(--viz-bg);
	color: var(--viz-text);
	min-height: 100%;
	font: 14px/1.5 var(--asam-typography-font-family, 'Segoe UI', sans-serif);
}
.viz-shell.dark {
	color-scheme: dark;
}
.viz-shell[data-size='large'] {
	--viz-control: 40px;
}
.viz-shell[data-size='big'] {
	--viz-control: 36px;
}
.viz-shell[data-size='small'] {
	--viz-control: 28px;
}
body {
	margin: 0;
}
.viz-shell * {
	box-sizing: border-box;
}
.viz-shell nav {
	display: flex;
	align-items: center;
	gap: 16px;
	padding: 16px 3vw;
	border-bottom: 1px solid var(--viz-border);
	background: var(--viz-surface);
	flex-wrap: wrap;
}
.viz-shell nav strong {
	margin-right: auto;
	letter-spacing: 0.12em;
}
.viz-shell small {
	font-size: 10px;
	font-weight: 400;
}
.viz-shell button:not([class*='el-']),
.viz-shell input:not([class*='el-']),
.viz-shell select:not([class*='el-']) {
	font: inherit;
	color: inherit;
	background: var(--viz-surface);
	border: 1px solid var(--viz-border);
	border-radius: var(--asam-radius-control, 4px);
	min-height: var(--viz-control);
	line-height: 20px;
	padding: 3px 10px;
}
.viz-shell button:not([class*='el-']) {
	cursor: pointer;
}
.viz-shell button:not([class*='el-']):hover,
.viz-shell [aria-current='page']:not(.el-button) {
	border-color: var(--asam-semantic-primary-foreground);
	color: var(--asam-semantic-primary-foreground);
}
.viz-shell :focus-visible {
	outline: 3px solid var(--asam-semantic-focus);
	outline-offset: 3px;
}
.viz-shell input:not([class*='el-'])[type='checkbox'] {
	min-height: 0;
}
.viz-page {
	max-width: 1600px;
	margin: auto;
	padding: 28px 3vw;
}
.viz-heading {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: 16px;
	margin-bottom: 22px;
}
.viz-heading h1 {
	font-size: 32px;
	letter-spacing: -0.035em;
	margin: 4px 0;
}
.viz-heading p {
	margin: 0;
	color: var(--asam-color-text-secondary, #657983);
}
.viz-eyebrow {
	font-size: 11px;
	letter-spacing: 0.12em;
}
.viz-toolbar {
	display: flex;
	align-items: end;
	gap: 12px;
	flex-wrap: wrap;
	margin-bottom: 16px;
}
.viz-toolbar label {
	display: grid;
	gap: 4px;
	font-size: 12px;
}
.viz-shell nav label {
	display: flex;
	align-items: center;
	gap: 5px;
}
.viz-analysis-grid {
	display: grid;
	grid-template-columns: 1.4fr 1fr;
	gap: 18px;
	margin-top: 24px;
}
.viz-analysis-grid > .viz-chart:first-child {
	grid-column: 1/-1;
}
.viz-monitor-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 16px;
	margin-top: 24px;
}
.viz-chart {
	min-width: 0;
	padding: 18px;
	background: var(--viz-surface);
	border: 1px solid var(--viz-border);
	border-radius: var(--asam-radius-card, 8px);
}
.viz-chart header {
	display: flex;
	justify-content: space-between;
}
.viz-chart h2 {
	font-size: 15px;
	margin: 0 0 12px;
}
.viz-chart .asam-form-section {
	border: 0;
	padding: 0;
	display: flex;
	gap: 12px;
	font-size: 12px;
}
.viz-chart .asam-form-section-title {
	font-size: 11px;
	color: var(--asam-color-text-secondary, #657983);
}
.viz-plot {
	width: 100%;
}
.viz-chart summary {
	cursor: pointer;
	font-size: 12px;
	margin-top: 12px;
}
.viz-table {
	max-height: 260px;
	overflow: auto;
}
.viz-table table {
	border-collapse: collapse;
	width: 100%;
	font-size: 12px;
}
.viz-table th,
.viz-table td {
	text-align: left;
	padding: 6px;
	border-bottom: 1px solid var(--viz-border);
}
.viz-status {
	border: 1px solid var(--viz-border);
	padding: 6px 12px;
	border-radius: 20px;
}
.viz-shell .asam-card-group {
	margin: 18px 0;
}
@media (max-width: 700px) {
	.viz-analysis-grid,
	.viz-monitor-grid {
		grid-template-columns: minmax(0, 1fr);
	}
	.viz-heading h1 {
		font-size: 26px;
	}
	.viz-shell nav {
		gap: 9px;
	}
	.viz-shell nav strong {
		width: 100%;
	}
	.viz-toolbar input:not([class*='el-']) {
		max-width: 100%;
	}
	.viz-chart {
		padding: 12px;
	}
	.viz-page {
		padding: 20px 14px;
	}
}
@media (prefers-reduced-motion: no-preference) {
	.viz-shell button:not([class*='el-']) {
		transition:
			border-color 0.15s,
			color 0.15s;
	}
	.viz-page {
		animation: viz-enter 0.18s ease-out;
	}
	@keyframes viz-enter {
		from {
			opacity: 0.4;
			transform: translateY(3px);
		}
		to {
			opacity: 1;
			transform: none;
		}
	}
}

