		for (const row of rows) {
			const key = JSON.stringify([typeof row?.id, row?.id]);
			if (!row || !stableId(row.id) || ids.has(key))
				throw createAsamMessageError(
					'区块标识非法或重复',
					'app.templates.workbench.idsInvalid'
