			throw createAsamMessageError('目标标识不能为空', 'app.templates.workbench.targetEmpty');
	for (const task of input.tasks)
		if (
			typeof task.title !== 'string' ||
			!task.status ||
			typeof task.status.label !== 'string' ||
			!Array.isArray(task.assignees)
